-- G1 (6. okt. 2026): godkendte nedgange. Jan har sagt ja til kun at sænke felter, hvor allergenet slet ikke nævnes i
-- ingredienslisten (ingen nøgleord på dansk, engelsk, tysk, hollandsk, svensk, norsk, finsk eller fransk som understreng).
-- Rører IKKE products; markerer kun rækker i gennemgangstabellen. Selve skrivningen sker først i allergen-reanalyze (apply_down).
alter table public.allergen_reanalysis_down_20261006 add column if not exists approved_allergens text[] not null default '{}';

create table if not exists public.products_allergen_down_backup_20261006 (
  product_id uuid primary key,
  old_flags jsonb,
  old_quality text,
  old_method text,
  saved_at timestamptz not null default now()
);
alter table public.products_allergen_down_backup_20261006 enable row level security;
grant all on public.products_allergen_down_backup_20261006 to service_role;

