update public.allergen_reanalysis_down_20261006 d
set approved_allergens = coalesce((
      select array_agg(u.al order by u.al)
      from unnest(d.down_allergens) as u(al)
      join rx on rx.a = u.al
      where d.old_flags->>u.al in ('yes', 'traces')
        and coalesce(d.new_flags->>u.al, 'no') = 'no'
        and d.ingredients_text !~* rx.re
    ), '{}'),
    decision = null
where d.applied_at is null;

update public.allergen_reanalysis_down_20261006
set decision = 'approved'
where cardinality(approved_allergens) > 0 and applied_at is null;
